(3, 'Website', 'adsense', '<!-- Live Web Design Ad Banner -->\r\n<style>\r\n  .ad-banner-container {\r\n    background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);\r\n    border: 2px solid #25d366;\r\n    border-radius: 16px;\r\n    padding: 24px;\r\n    max-width: 380px;\r\n    color: #ffffff;\r\n    font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\r\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);\r\n    text-align: center;\r\n    position: relative;\r\n    overflow: hidden;\r\n    margin: 20px auto;\r\n  }\r\n\r\n  .ad-banner-badge {\r\n    background-color: #25d366;\r\n    color: #0c0f12;\r\n    font-size: 12px;\r\n    font-weight: 800;\r\n    text-transform: uppercase;\r\n    padding: 4px 12px;\r\n    border-radius: 20px;\r\n    display: inline-block;\r\n    margin-bottom: 12px;\r\n    letter-spacing: 1px;\r\n  }\r\n\r\n  .ad-banner-title {\r\n    font-size: 22px;\r\n    font-weight: 700;\r\n    margin: 0 0 10px 0;\r\n    line-height: 1.3;\r\n    color: #ffffff;\r\n  }\r\n\r\n  .ad-banner-title span {\r\n    color: #25d366;\r\n  }\r\n\r\n  .ad-banner-desc {\r\n    font-size: 14px;\r\n    color: #cbd5e1;\r\n    margin: 0 0 20px 0;\r\n    line-height: 1.5;\r\n  }\r\n\r\n  .ad-banner-btn {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 10px;\r\n    background-color: #25d366;\r\n    color: #ffffff;\r\n    text-decoration: none;\r\n    font-weight: 700;\r\n    font-size: 16px;\r\n    padding: 12px 20px;\r\n    border-radius: 50px;\r\n    transition: all 0.3s ease;\r\n    animation: pulse-glow 2s infinite;\r\n  }\r\n\r\n  .ad-banner-btn:hover {\r\n    background-color: #1ebd59;\r\n    transform: translateY(-2px);\r\n  }\r\n\r\n  @keyframes pulse-glow {\r\n    0% {\r\n      box-shadow: 0 0 0 0 rgba(37, 211, 102, 0.7);\r\n    }\r\n    70% {\r\n      box-shadow: 0 0 0 12px rgba(37, 211, 102, 0);\r\n    }\r\n    100% {\r\n      box-shadow: 0 0 0 0 rgba(37, 211, 102, 0);\r\n    }\r\n  }\r\n</style>\r\n\r\n<div class=\"ad-banner-container\">\r\n  <div class=\"ad-banner-badge\">Web Development Services</div>\r\n  <h3 class=\"ad-banner-title\">Need a <span>Professional Website</span> for Your Business?</h3>\r\n  <p class=\"ad-banner-desc\">We build modern, fast, and responsive websites tailored to your brand.</p>\r\n  \r\n  <a href=\"https://wa.me/250786354884?text=Hello!%20I%20saw%20your%20banner%20and%20I%20want%20to%20create%20a%20website.\" \r\n     target=\"_blank\" \r\n     class=\"ad-banner-btn\">\r\n     💬 Order on WhatsApp\r\n  </a>\r\n</div>', NULL, '', 'hero', 1, 0, '2026-07-22 20:27:20', '2026-07-23 06:15:12');

