INSERT INTO `jobs` (`id`, `company_id`, `company_name`, `company_logo`, `category_id`, `title`, `slug`, `description`, `responsibilities`, `requirements`, `qualifications`, `benefits`, `how_to_apply`, `application_url`, `application_email`, `province`, `district`, `location`, `employment_type`, `experience_level`, `education_level`, `salary_currency`, `salary_period`, `application_deadline`, `is_featured`, `status`, `views`, `applications_count`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, 'Rwanda Development Board', NULL, 1, 'Senior Software Developer', 'senior-software-developer-rdb', 'We are looking for a talented Senior Software Developer to join our Digital Innovation team. You will be responsible for designing, developing, and maintaining web applications that support Rwanda\'s economic development initiatives.', 'Design and develop scalable web applications\nLead technical architecture decisions\nMentor junior developers\nConduct code reviews\nCollaborate with cross-functional teams\nParticipate in agile ceremonies', '5+ years of software development experience\nProficiency in PHP, JavaScript, Python\nExperience with MySQL and PostgreSQL\nKnowledge of cloud services (AWS/Azure)\nStrong problem-solving skills', 'Bachelor\'s degree in Computer Science or related field\nProfessional certifications are a plus\nExperience with government projects preferred', 'Competitive salary\nHealth insurance\nAnnual leave\nProfessional development opportunities\nModern work environment', NULL, NULL, NULL, 'Kigali', 'Gasabo', 'Kimihurura', 'Full-time', '5+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-08-30', 1, 'published', 7, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:08:52', '2026-07-17 15:08:52'),
(2, 2, 'Bank of Kigali', NULL, 4, 'Financial Analyst', 'financial-analyst-bk', 'Bank of Kigali is seeking a skilled Financial Analyst to join our Risk Management department. The ideal candidate will analyze financial data, prepare reports, and support strategic decision-making.', 'Analyze financial statements and market trends\nPrepare monthly financial reports\nEvaluate investment opportunities\nMonitor risk indicators\nSupport budgeting and forecasting\nCollaborate with management on financial strategy', '3+ years of financial analysis experience\nAdvanced Excel and financial modeling skills\nKnowledge of Rwandan financial regulations\nStrong analytical and communication skills', 'Bachelor\'s degree in Finance, Economics, or Accounting\nCFA or ACCA certification is an advantage\nMBA preferred', 'Competitive salary\nPerformance bonuses\nMedical insurance\nPension scheme\nTraining opportunities', NULL, NULL, NULL, 'Kigali', 'Nyarugenge', 'City Center', 'Full-time', '3+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-08-15', 1, 'published', 2, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:09:07', '2026-07-17 15:09:07'),
(3, 3, 'Marriott Hotel Kigali', NULL, 9, 'Front Office Manager', 'front-office-manager-marriott', 'Marriott Hotel Kigali is looking for an experienced Front Office Manager to oversee daily front desk operations and ensure exceptional guest experiences.', 'Manage front desk operations and staff\nHandle guest complaints and escalations\nOversee reservations and check-in/check-out processes\nTrain and supervise front office team\nEnsure compliance with brand standards\nPrepare daily operations reports', '4+ years of hospitality front office experience\nStrong leadership and communication skills\nProficiency in hotel management systems\nExcellent problem-solving abilities', 'Bachelor\'s degree in Hospitality Management\nMarriott brand experience preferred\nMulti-language skills are a plus', 'Competitive salary\nMeal allowances\nUniform provided\nCareer advancement opportunities\nStaff discounts', NULL, NULL, NULL, 'Kigali', 'Gasabo', 'Kimihurura', 'Full-time', '4+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-09-01', 0, 'published', 0, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:09:11', '2026-07-17 15:09:11'),
(4, 4, 'Rwanda National Police', NULL, 18, 'Investigation Officer', 'investigation-officer-rnp', 'Rwanda National Police is recruiting Investigation Officers to join our Criminal Investigation Department. This role involves conducting thorough investigations and ensuring justice is served.', 'Conduct criminal investigations\nGather and analyze evidence\nInterview witnesses and suspects\nPrepare investigation reports\nCollaborate with prosecutors\nMaintain case files and records', 'Bachelor\'s degree in Criminology, Law, or related field\nStrong analytical and observation skills\nGood physical fitness\nClean criminal record\nWillingness to work irregular hours', 'Bachelor\'s degree in relevant field\nPolice academy training preferred\nKnowledge of Rwandan laws and regulations', 'Government salary scale\nHousing allowance\nMedical coverage\nPension benefits\nCareer development', NULL, NULL, NULL, 'Kigali', 'Nyarugenge', 'Kacyiru', 'Full-time', '2+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-08-20', 1, 'published', 3, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:09:18', '2026-07-17 15:09:18'),
(5, 5, 'MTN Rwanda', NULL, 19, 'Network Engineer', 'network-engineer-mtn', 'MTN Rwanda is seeking a skilled Network Engineer to design, implement, and maintain our telecommunications network infrastructure across the country.', 'Design and implement network solutions\nMonitor network performance and uptime\nTroubleshoot network issues\nPerform routine maintenance and upgrades\nDocument network configurations\nSupport new technology rollouts', '3+ years of network engineering experience\nCCNA/CCNP certification\nExperience with Huawei or Ericsson equipment\nStrong TCP/IP and routing knowledge\nLinux administration skills', 'Bachelor\'s degree in Telecommunications or IT\nCisco certifications required\n5G experience is a plus', 'Competitive salary\nInternet allowance\nHealth insurance\nAnnual bonus\nRelocation assistance', NULL, NULL, NULL, 'Kigali', 'Gasabo', 'Remera', 'Full-time', '3+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-09-15', 1, 'published', 0, 0, 0, '2026-07-17 10:10:51', '2026-07-17 12:22:45', '2026-07-17 14:22:45'),
(6, 6, 'SOS Children\'s Villages Rwanda', NULL, 11, 'Programme Coordinator', 'programme-coordinator-sos', 'SOS Children\'s Villages Rwanda is looking for a Programme Coordinator to manage and develop family-strengthening programs that support vulnerable children and families.', 'Coordinate programme activities across sites\nMonitor programme quality and impact\nManage budgets and resources\nBuild partnerships with stakeholders\nTrain and supervise programme staff\nPrepare programme reports', '4+ years of programme management experience in NGOs\nExperience in child protection or social work\nStrong project management skills\nExcellent written and verbal communication', 'Bachelor\'s degree in Social Work, Development Studies, or related field\nMaster\'s degree preferred\nExperience with international NGOs', 'Competitive NGO salary\nHealth insurance\nProfessional development\nAnnual leave\nMission opportunities', NULL, NULL, NULL, 'Kigali', 'Kicukiro', 'Kanombe', 'Full-time', '4+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-08-25', 0, 'published', 0, 0, 0, '2026-07-17 10:10:51', '2026-07-17 12:22:56', '2026-07-17 14:22:56'),
(7, 7, 'Rwanda Agricultural Board', NULL, 8, 'Agricultural Research Officer', 'agricultural-research-officer-rab', 'Rwanda Agricultural Board is recruiting Agricultural Research Officers to conduct research aimed at improving crop yields and farming practices in Rwanda.', 'Conduct field research on crop production\nCollect and analyze agricultural data\nDevelop improved farming techniques\nTrain farmers on best practices\nCollaborate with international research partners\nPublish research findings', '3+ years of agricultural research experience\nField work capability\nData analysis skills\nKnowledge of Rwandan agricultural systems', 'Bachelor\'s degree in Agriculture or related field\nMaster\'s degree preferred\nPublications in agricultural journals are a plus', 'Government salary scale\nResearch allowances\nField equipment provided\nConference attendance\nSabbatical opportunities', NULL, NULL, NULL, 'Southern', 'Huye', 'Huye Town', 'Full-time', '3+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-09-10', 0, 'published', 0, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:09:21', '2026-07-17 15:09:21'),
(8, 8, 'Rwanda Information Society Authority', NULL, 1, 'ICT Project Manager', 'ict-project-manager-risa', 'Rwanda Information Society Authority is looking for an ICT Project Manager to lead the implementation of digital transformation projects across government institutions.', 'Lead ICT project planning and execution\nManage project budgets and timelines\nCoordinate with government stakeholders\nOversee technical teams\nEnsure project quality standards\nReport on project progress', '5+ years of ICT project management experience\nPMP or PRINCE2 certification\nExperience with government IT projects\nStrong stakeholder management skills', 'Bachelor\'s degree in IT or related field\nMaster\'s degree preferred\nGovernment project experience required', 'Competitive salary\nHealth insurance\nTraining budget\nFlexible working\nAnnual bonus', NULL, NULL, NULL, 'Kigali', 'Gasabo', 'Kimihurura', 'Full-time', '5+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-09-30', 1, 'published', 4, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:09:24', '2026-07-17 15:09:24'),
(9, 2, 'Bank of Kigali', NULL, 12, 'Finance Intern', 'finance-intern-bk', 'Bank of Kigali offers internship opportunities for recent graduates to gain practical experience in the banking and finance sector.', 'Assist with daily accounting tasks\nSupport financial report preparation\nHelp with data entry and reconciliation\nObserve banking operations\nComplete assigned projects\nParticipate in training sessions', 'Currently enrolled in or recently graduated from a relevant degree program\nStrong attention to detail\nProficiency in Microsoft Office\nEagerness to learn', 'Bachelor\'s degree in Finance, Accounting, or related field (in progress or recently completed)\nStrong academic record', 'Monthly stipend\nMentorship program\nNetworking opportunities\nPotential for full-time employment\nProfessional development', NULL, NULL, NULL, 'Kigali', 'Nyarugenge', 'City Center', 'Internship', 'Entry Level', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-08-01', 0, 'published', 0, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:09:27', '2026-07-17 15:09:27'),
(10, 5, 'MTN Rwanda', NULL, 13, 'Sales Executive', 'sales-executive-mtn', 'MTN Rwanda is hiring Sales Executives to drive subscriber growth and revenue through B2B and B2C sales activities across assigned territories.', 'Identify and pursue new business opportunities\nMeet monthly sales targets\nBuild and maintain client relationships\nConduct product demonstrations\nPrepare sales reports\nAttend industry events', '2+ years of sales experience preferably in telecom\nStrong negotiation skills\nSelf-motivated and target-driven\nValid driver\'s license', 'Bachelor\'s degree in Business, Marketing, or related field\nSales certifications are a plus', 'Competitive base salary plus commission\nHealth insurance\nPhone allowance\nPerformance bonuses\nCareer growth', NULL, NULL, NULL, 'Kigali', 'Gasabo', 'Nyabugogo', 'Full-time', '2+ years', 'Bachelor\'s Degree', 'RWF', 'monthly', '2026-08-10', 0, 'published', 0, 0, 0, '2026-07-17 10:10:51', '2026-07-17 22:09:36', '2026-07-17 15:09:36'),
(11, NULL, 'Tecno Rwanda', 'logos/img_6a5a1b7052a29.png', 3, 'Cashier', 'cashier', 'We', 'gghijokl', 'fguhijokl', 'fghbjnkm', 'rghjk', 'dfghjk', NULL, NULL, 'Eastern', 'Kayonza', '', 'Contract', '', '', 'RWF', 'monthly', '2026-07-31', 1, 'published', 0, 0, 0, '2026-07-17 12:09:20', '2026-07-17 12:13:02', '2026-07-17 14:13:02'),
(12, NULL, 'Tecno Rwanda', 'logos/img_6a5a1c351385f.png', 3, 'Cashier', 'cashier-1784290357', 'We', 'gghijokl', 'fguhijokl', 'fghbjnkm', 'rghjk', 'dfghjk', NULL, NULL, 'Eastern', 'Kayonza', '', 'Contract', '', '', 'RWF', 'monthly', '2026-07-31', 1, 'published', 1, 0, 0, '2026-07-17 12:12:37', '2026-07-17 22:08:49', '2026-07-17 15:08:49'),
(13, NULL, 'Help a Child Rwanda', 'logos/img_6a5aaa2d6fe21.jpg', 17, 'Driver', 'driver', 'JOB ADVERTISEMENT\r\nDriver (One-Year Fixed-Term Contract)\r\nLocation: Kimihurura.\r\nContract Type: Fixed-Term (One Year)\r\nReporting To: Finance and Administration Officer\r\nApplication Deadline: 27th July 2026\r\nAbout the Organization\r\nHelp a Child Rwanda is a Christian international non-profit organization, founded in 1968. The organization is committed to improving the wellbeing of vulnerable children, families, and their communities through child-centered community development programmes. Its mission is to promote a promising future for children in need, their families, and the communities in which they live.\r\nPurpose of the advert:  Recruitment of the car driver.', 'The successful candidate will:\r\n\r\nSafely transport staff, consultants, partners, and authorized visitors to official destinations.\r\nEnsure assigned vehicles are clean, roadworthy, and properly maintained.\r\nConduct daily vehicle inspections and promptly report mechanical faults or accidents.\r\nMaintain accurate vehicle logbooks, fuel records, mileage records, and maintenance schedules.\r\nEnsure compliance with traffic laws, road safety regulations, and the organization\'s transport policies.\r\nSupport logistics activities, including the transportation of project materials and equipment.\r\nMaintain confidentiality and demonstrate professionalism when interacting with staff, partners, and beneficiaries.\r\nPerform any other duties assigned by the supervisor.', 'The ideal candidate should demonstrate:\r\nIntegrity and professionalism.\r\nReliability and punctuality.\r\nGood organizational and time-management skills.\r\nStrong commitment to safety and customer service.\r\nAbility to work independently and as part of a team.', 'Applicants should possess:\r\nA valid driver\'s license Category B.\r\nA minimum of Five (5) years of professional driving experience.\r\nAt least a secondary school certificate or equivalent.\r\nGood knowledge of road safety regulations and defensive driving practices.\r\nBasic knowledge of vehicle maintenance.\r\nStrong communication and interpersonal skills.\r\nAbility to work under pressure and travel to field locations when required.\r\nExperience working with private and public institutions, NGOs, development partners, or international organizations is an added advantage.', 'One-year fixed-term contract.\r\nCompetitive salary and benefits in accordance with the organization\'s policies.', 'Interested candidates should submit the following:\r\nA cover letter.\r\nAn updated Curriculum Vitae (CV).\r\nCopies of a valid driver\'s license category B.\r\nCopies of academic and professional certificates.\r\nContact details of at least two professional referees.\r\nApplications should be sent to Info@hacrwanda.org\r\n\r\nThe closing date for applications is 27th July 2026 at 9:00 AM.\r\n\r\nOnly shortlisted candidates will be contacted.', '', 'info@hacrwanda.org', 'Kigali', 'Gasabo', 'Kimihurura', 'Full-time', '5 years above', 'At least a secondary school certificate or equivalent.', 'RWF', 'monthly', '2026-07-27', 0, 'archived', 224, 0, 1, '2026-07-17 22:18:21', '2026-07-28 07:15:44', NULL);
INSERT INTO `jobs` (`id`, `company_id`, `company_name`, `company_logo`, `category_id`, `title`, `slug`, `description`, `responsibilities`, `requirements`, `qualifications`, `benefits`, `how_to_apply`, `application_url`, `application_email`, `province`, `district`, `location`, `employment_type`, `experience_level`, `education_level`, `salary_currency`, `salary_period`, `application_deadline`, `is_featured`, `status`, `views`, `applications_count`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(14, NULL, 'BRAC', 'logos/img_6a5d54f49451c.png', 20, 'Field Data Collectors/ Enumerators', 'field-data-collectors-enumerators', 'Job Location: Fields where BRAC International has operations in different Districts of Rwanda  (Muhanga, Ruhango, Nyanza, Huye, Nyamagabe & Nyaruguru) \r\nABOUT BRAC \r\n\r\nBRAC International (BI), a leading non-profit organization, is on a mission to empower people and communities facing poverty, illiteracy, disease, and social injustice. Our vision is to create a world free from exploitation and discrimination, where everyone has the opportunity to realize their potential. We design proven, scalable solutions that equip people with the support and confidence they need to achieve their potential. \r\n\r\nWe are seeking to hire qualified, dedicated and experienced Rwandan Nationals for the “Field Data  Collectors – Enumerators” position to support our Monitoring and Evaluation Unit. Enumerators will  work in the field where BRAC International has operations in different districts of Rwanda under the  guidance and supervision of the Monitoring & Learning Officer, Branch Manager, Regional Manager  and will report directly to the country Monitoring & Learning Manager. \r\n\r\nJob Location: Fields where BRAC International has operations in different Districts of Rwanda  (Muhanga, Ruhango, Nyanza, Huye, Nyamagabe & Nyaruguru)', 'Pre- enumeration duties: \r\n\r\nThrough training, develop sufficient comprehension of the programs, research protocol, ethical  requirements, the study population and the study tools. \r\nWork with project teams to mobilize communities for interviews and discussions. Enumeration duties: \r\nCollect data by using structured interviews with the sampled respondents and service providers  using pre-developed questionnaires. \r\nEnsure completeness of forms for accuracy and consistency after the data collection. ∙ Facilitate qualitative interviews – Key informant Interviews (KIIs) and Focus Group Discussion  (FGDs). \r\nEnsure proper and accurate transcription of information gathered through interviews and Focus  Group Discussion (FGDs). \r\n\r\nPost-enumeration duties:\r\n\r\nHand in assignments as instructed by the MEL team and any other notes on observations made  during the interviews. \r\nEnsure that enumerator checking is complete. \r\nAccount for all questionnaires/guides and equipment. \r\nTurn over all literature and materials used in the survey to the M&E team', 'Education: A university degree in statistics, social sciences, public health, or a related field. ∙ \r\n\r\nLanguage Skills: Fluency in the local languages spoken by the target population (e.g.,  Kinyarwanda, English). \r\n\r\nExperience in both qualitative and quantitative data collections for monitoring, evaluation, and  impact assessment purposes. \r\nPrior minimum (2 years) experience in conducting field research work using participatory  approaches in different locations in the country is essential. \r\n\r\nPrior experience in interviewing and facilitating FDGs (Focus Group Discussions) and in-depth  interviews \r\nExperience and knowledge on mobile data collection applications. \r\nDisplays exemplary positive behaviors for consistency, predictability and reliability at work to  complete assignments and meet deadlines. \r\nExtensive knowledge of word processing and spreadsheet software (Word, Excel). ∙ Good working knowledge of English and Kinyarwanda. \r\nCandidates are required to present proof of experience in data collection using various  methods, both qualitative and quantitative, is a sound practice, especially in roles where data driven decision-making is crucial.', 'Integrity: We approach our work with honesty and integrity. \r\nInnovation: We innovate and iterate to improve our impact. \r\nInclusiveness: We foster inclusion to reach those who need it most. \r\nEffectiveness: We strive for effectiveness to better serve people in poverty.', 'Full-time Job', 'If you feel you are the right match for the above-mentioned position, please follow the application  instructions accordingly: \r\nQualified and interested candidates are recommended to email their Resume with a signed cover letter  in a single PDF format and any supporting documents to bracrwandarecruitment@gmail.com. \r\nPlease ensure that your application package includes the following: \r\nAn updated CV and years of experience. \r\nProof of experience in data collection using various methods, both qualitative and quantitative, is a sound practice, especially in roles where data-driven decision-making is crucial.', '', 'bracrwandarecruitment@gmail.com', 'Southern', 'HUYE DISTRICT', '', 'Full-time', '2 YEARS', 'Bachelor&amp;amp;amp;amp;amp;amp;amp;#039;s Degree', 'RWF', 'monthly', '2026-07-26', 1, 'archived', 35, 0, 1, '2026-07-19 22:51:33', '2026-07-26 05:57:13', NULL),
(15, NULL, 'TEACH Rwanda', 'logos/img_6a5d575b91d1f.png', 4, 'School Bursar', 'school-bursar', 'TEACH Rwanda has a decade of experience building teacher capacity and transforming the lives of Rwandan children though teacher mentoring and child-centred, evidence-based teaching practices.', 'Bright School is seeking a highly organised and proactive School Bursar to lead the school\'s financial, administrative and operational systems, ensuring accountability, efficiency and long-term sustainability. Reporting to the Head Teacher and working in close collaboration with TEACH Rwanda, the Bursar will oversee financial management, school administration and the school feeding programme, while supporting the effective implementation of TEACH Rwanda programmes within the school. The role will strengthen systems, support informed decision-making, and ensure compliance with organisational policies and procedures. Through sound financial management, effective collaboration and a commitment to continuous improvement, the Bursar will play a key role in creating a well-managed school that enables high-quality teaching and learning.\r\n\r\nSchool Operations & Administration\r\nEnsure efficient, well-organised, and responsive school operations by maintaining accurate records, streamlining administrative systems, and fostering a professional, reliable, and service-oriented environment that enhances school operations and efficiency.\r\n•	Maintains efficient administrative systems that ensure accurate record-keeping, effective communication and the smooth operation of the school.\r\n•	Manages school communications, ensuring information is shared accurately, professionally and in a timely manner.\r\n•	Coordinates office operations, resolving administrative issues and ensuring compliance with school procedures and policies.\r\n•	Manages office resources efficiently, ensuring adequate supplies to support uninterrupted school operations.\r\n•	Provides effective administrative support to the Head Teacher and school leadership through accurate documentation, meeting coordination and timely follow-up.\r\n•	Maintains professionalism, confidentiality and positive working relationships with students, parents, staff, TEACH Rwanda, suppliers and other stakeholders.\r\n\r\nFinancial Management & Accountability\r\nEnsures financial integrity, stability and sustainability through accurate record-keeping, transparent reporting, effective budget management, and full compliance with organisational and regulatory requirements.\r\n•	Maintains accurate and transparent financial records, reconciliations and reports to support effective school financial management.\r\n•	Manages school income and expenditure, ensuring accurate payment records, timely follow-up and clear financial updates.\r\n•	Supports the development and monitoring of annual and termly budgets aligned with school priorities.\r\n•	Tracks expenditure against budgets, identifies variances and provides timely financial updates to support decision-making.\r\n•	Analyses financial performance and recommends improvements to strengthen efficiency and sustainability.\r\n•	Manages financial controls, ensuring expenses are processed accurately and in line with approved procedures and policies.\r\n•	Oversees procurement processes and documentation, ensuring transparency, value for money and compliance with audit and statutory requirements.\r\n•	Supports the development and improvement of financial systems, policies and processes to strengthen efficiency and accountability.\r\n•	Develop, manage and oversee the school\'s payroll system, ensuring the accurate and timely processing of employee salaries, statutory deductions, and all government tax obligations.\r\n\r\nSchool Feeding Programme & Kitchen Operations Management\r\nOversees efficient and accountable kitchen operations by managing staff, controlling costs, ensuring consistent food supply, and maintaining accurate financial reporting to support a reliable school feeding programme.\r\n•	Ensures smooth kitchen operations by maintaining organisation, addressing challenges and upholding cleanliness and food handling standards.\r\n•	Supervises and supports kitchen staff, ensuring clear roles, accountability, effective teamwork and professional conduct.\r\n•	Manages kitchen finances through effective budgeting, accurate cost tracking, financial reporting and identification of efficiency improvements.\r\n•	Manages food and supply procurement efficiently, maintaining reliable supplier relationships, adequate stock levels and accurate purchasing documentation.\r\n\r\nCommunication & Stakeholder Relationships\r\nBuilds and maintains strong, professional relationships with parents, colleagues, suppliers, and TEACH Rwanda teams through clear, timely, and respectful communication that supports collaboration, trust, and effective problem-solving.\r\n•	Communicates clearly and professionally, ensuring timely information sharing, responsive follow-up and effective stakeholder engagement.\r\n•	Builds respectful, trust-based relationships with stakeholders and approaches challenges with a professional, solution-oriented mindset.\r\n•	Collaborates effectively with school and TEACH Rwanda leadership, supporting coordination, information sharing and alignment across teams.', '•	Educational Qualification: A2 or A1 degree in accounting, CPA, or a related field.\r\n•	Technical Skills: Proficiency in computer systems, QuickBooks, KudiBooks, word processing, and internet usage. Knowledge of office equipment and procedures, with strong organizational and time management skills.\r\n•	Analytical & Problem-Solving Skills: Ability to analyze information and resolve issues effectively. Takes proactive steps to improve processes, solve problems, and contribute to team success.\r\n•	Communication Skills: Strong verbal and written communication skills in Kinyarwanda and English.\r\n•	Attention to Detail: Ability to accurately read, enter, and update records. Prioritizes tasks effectively to meet deadlines and maintain efficiency.\r\n•	Time management: Prioritizes tasks effectively to meet deadlines and maintain efficiency.\r\n•	Responsiveness: Ability to follow up on recommendations and feedback from the school head teacher and TEACH Rwanda.\r\n•	Willingness to Learn: Eagerness to develop new skills, particularly related to education innovation and child-development', 'Personal attributes\r\n•	Open-mindedness and lifelong learning: Demonstrates curiosity, a growth mindset, and a commitment to continuous professional development\r\n•	Adaptability: Embraces diverse learning styles, environments, and challenges with flexibility and resilience.\r\n•	Collaboration and respect: Works effectively with colleagues, students, and stakeholders to foster a positive and productive environment. Values diverse perspectives and treats all individuals with dignity.', 'Salary and benefits\r\nA salary of 347,244 Rwf gross per month plus standard benefits (national holidays, medical insurance, family leave, etc.). TR office in Muhanga. Computer and internet/phone airtime provided. Open-ended contract after successful completion of 3-month probationary period. Annual performance review. 21 days paid leave.', 'Please apply using the email address teachrwandahr@gmail.com with the following:\r\n-	Cover letter referencing the experience you have specific to the roles and responsibilities identified above. \r\n-	Up-to-date CV', '', 'teachrwandahr@gmail.com', '', '', '', 'Full-time', 'Entry level (1 to 3 years of experience)', 'A2 or A1 degree in Accounting, CPA or a related field.', 'RWF', 'monthly', '2026-07-24', 0, 'archived', 18, 0, 1, '2026-07-19 23:01:47', '2026-07-24 15:25:49', NULL),
(16, NULL, 'Akagera Sacco Kayonza (ASK)', 'logos/img_6a5d59bdab23f.png', 17, 'Driver', 'driver-1784502717', 'Akagera Sacco Kayonza (ASK) is a District Savings and Credit Cooperative (D-SACCO) established following the consolidation of Tuelve Umurenge Sacco’s operating within Kayonza District, in accordance with the Government of Rwanda SACCO consolidation framework. ASK is duly registered under RCA Certificate No. N° RGDG013385 and licensed by the National Bank of Rwanda (BNR).\r\n\r\nIn accordance with Law N° 072/2021 of 05/11/2021 governing Deposit-Taking Microfinance Institutions, ASK is authorized to carry out microfinance activities in the Republic of Rwanda.\r\n\r\nTo achieve its mission and strengthen institutional efficiency, ASK is looking for a qualified, competent, committed, proactive, and self-motivated individual to fill the following vacant position:\r\n\r\nJOB ADVERT- DRIVER\r\n\r\nTo achieve its mission and strengthen institutional efficiency, ASK is seeking to recruit a competent, committed, professional, and self-motivated DRIVER to join the institution.', 'Under the supervision and guidance of the Logistics Officer, the DRIVER shall perform the following duties and responsibilities:\r\n\r\nWork diligently on the assigned work on time and to produce results;\r\n Comply with the instructions of the employer or his/her representative;\r\nTake good care of and manage the equipment assigned to him/her in his/her work;\r\nBe at work and respect working days and hours;\r\nMaintain the confidentiality of work;\r\nFollow the principles and codes of conduct governing the business activities of ASK;\r\nSafely transport staff, visitors, documents, cash (when authorized), and other official materials to designated locations. \r\nEnsure the assigned vehicle is clean, roadworthy, and in good working condition at all times. \r\n Conduct daily vehicle inspections (oil, water, tires, brakes, lights, fuel, and battery) before and after trips. \r\n Keep accurate vehicle logbooks, mileage, fuel consumption, and maintenance records. \r\n Ensure timely servicing and maintenance of the vehicle and promptly report any mechanical faults or accidents. \r\n Comply with all Rwanda traffic laws, road safety regulations, and Akagera SACCO policies. \r\nMaintain confidentiality and security when transporting official documents or authorized valuables. \r\n Plan travel routes efficiently to ensure timely arrival for official assignments. \r\n Ensure valid insurance, vehicle registration, and other required documents are always available in the vehicle. \r\nAssist with loading and unloading documents, equipment, or other official items when necessary. \r\nReport accidents, incidents, or vehicle damage immediately to the supervisor. \r\nDemonstrate professionalism, courtesy, and integrity when interacting with staff, members, and the public. \r\nPerform any other transport-related duties assigned by management. These responsibilities align with the operational needs of a district-level SACCO, which focuses on providing financial services efficiently across Kayonza District', 'Minimum of an Advanced Level Certificate (A2) \r\nPossession of a valid Rwandan driving license (Category B). \r\n At least 3 years of proven driving experience, preferably in a financial institution, NGO, government institution, or private organization. \r\nGood knowledge of Kayonza District and surrounding areas\r\nGood knowledge of Rwanda traffic laws, road safety regulations, and defensive driving practices. \r\nAbility to perform basic vehicle inspections and identify minor mechanical problems. \r\nGood communication and interpersonal skills. \r\nAbility to maintain confidentiality, honesty, and professionalism. \r\nPhysically fit and able to work flexible hours when required. \r\nNo criminal record and of high integrity. \r\nBasic literacy and record-keeping skills to maintain vehicle logbooks and travel records', 'Required Application Documents\r\n\r\nApplicants must submit the following documents:\r\n\r\nMotivation letter addressed to the Chairperson of the Board of Directors.\r\nUpdated Curriculum Vitae (CV) with at least three (3) professional referees and their contact details.\r\nCopy of academic Certificate and Driving license.\r\nCopy of National ID.\r\nCertificates of service rendered or previous employment certificates proving relevant experience.\r\nAny other relevant supporting documents proving experience and competencies.\r\nApplications must be submitted in soft copy as one single combined PDF document to the following email address: ask.recruitment26@gmail.com \r\nThe subject of the email must clearly indicate the position applied for: “Application for DRIVER.”\r\nDeadline for submission: 24th July, 2026 at 5:00 PM.\r\nLate applications will not be accepted.\r\nOnly shortlisted candidates will be contacted for the next stage of the recruitment process.\r\nAdditional Information\r\n\r\nASK promotes equal opportunity. All qualified candidates are encouraged to apply.\r\nNo fees or any form of compensation shall be requested at any stage of the recruitment process.\r\nBenefits are competitive and aligned with those offered by other financial institutions.', 'Full-time Job', 'Interested candidates should apply by clicking on this link:\r\nhttps://www.jobinrwanda.com/form/default-job-application-form?job_application_job=31417', '', '', 'Eastern', 'Kayonza', 'Mukarange', 'Full-time', 'Mid career (3 to 5 years of experience)', 'Licence and diploma A2', 'RWF', 'monthly', '2026-07-24', 0, 'archived', 204, 0, 1, '2026-07-19 23:11:57', '2026-07-24 15:24:26', NULL);
INSERT INTO `jobs` (`id`, `company_id`, `company_name`, `company_logo`, `category_id`, `title`, `slug`, `description`, `responsibilities`, `requirements`, `qualifications`, `benefits`, `how_to_apply`, `application_url`, `application_email`, `province`, `district`, `location`, `employment_type`, `experience_level`, `education_level`, `salary_currency`, `salary_period`, `application_deadline`, `is_featured`, `status`, `views`, `applications_count`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(17, NULL, 'Akagera Sacco Kayonza (ASK)', 'logos/img_6a5d5b441523e.png', 9, 'Cleaners', 'cleaners', 'Akagera Sacco Kayonza (ASK) is a District Savings and Credit Cooperative (D-SACCO) established following the consolidation of Tuelve Umurenge Sacco’s operating within Kayonza District, in accordance with the Government of Rwanda SACCO consolidation framework. ASK is duly registered under RCA Certificate No. N° RGDG013385 and licensed by the National Bank of Rwanda (BNR).\r\n\r\nTo achieve its mission and strengthen institutional efficiency, ASK is seeking to recruit a competent, committed, professional, and self-motivated CLEANERS to join the institution.', 'Under the supervision and guidance of the logistics officer, the CLEANER shall perform the following duties and responsibilities:\r\n\r\nWork diligently on the assigned work on time and to produce results;\r\n Comply with the instructions of the employer or his/her representative;\r\nTake good care of and manage the equipment assigned to him/her in his/her work;\r\nBe at work and respect working days and hours;\r\nMaintain the confidentiality of work;\r\nFollow the principles and codes of conduct governing the business activities of ASK;\r\nClean and maintain all office areas, including offices, meeting rooms, corridors, reception, washrooms, and surrounding premises. \r\n Sweep, mop, dust, vacuum, and polish floors, furniture, windows, and office equipment to maintain a clean and hygienic working environment. \r\n Ensure washrooms are clean, sanitized, and adequately stocked with soap, tissue paper, and other hygiene supplies. \r\n Empty waste bins, collect and dispose of garbage in accordance with environmental and organizational standards. \r\nReport any maintenance issues, damaged equipment, or safety hazards to the supervisor promptly. \r\n Ensure cleaning materials and equipment are properly used, stored, and maintained.\r\n  Monitor and report shortages of cleaning supplies and request replenishment when necessary. \r\nOpen and arrange offices before working hours and ensure offices are clean and orderly throughout the day. \r\nMaintain cleanliness of the compound, including walkways, parking areas, and other designated outdoor spaces. \r\nObserve health, safety, and hygiene standards while performing cleaning duties. \r\nMaintain confidentiality and demonstrate professionalism when working in office environments. \r\nSupport office operations by performing other related duties assigned by the supervisor or management.', 'Minimum of an Advanced level Certificate (A2) in any field. \r\nAt least one (1) year of relevant experience in cleaning or housekeeping, preferably in an office, financial institution, or similar organization. \r\nAbility to read and write in Kinyarwanda; knowledge of English and/or French is an added advantage. \r\nGood knowledge of cleaning methods, sanitation practices, and the safe use of cleaning materials and equipment. \r\n Physically fit and capable of performing cleaning duties, including lifting light materials and standing for extended periods. \r\nHigh standards of personal hygiene, cleanliness, honesty, and integrity. \r\nGood interpersonal and communication skills, with the ability to work well with staff, members, and visitors. \r\nAbility to work independently and as part of a team with minimal supervision. \r\nReliable, punctual, and committed to maintaining a clean, safe, and organized working environment. \r\nNo criminal record and willingness to comply with Akagera SACCO\'s policies, procedures, and code of conduct.', 'Required Application Documents\r\nApplicants must submit the following documents:\r\n\r\nMotivation letter addressed to the Chairperson of the Board of Directors.\r\nUpdated Curriculum Vitae (CV) with at least three (3) professional referees and their contact details.\r\nCopy of academic certificate.\r\nCopy of National ID.\r\nCertificates of service rendered or previous employment certificates proving relevant experience.\r\nAny other relevant supporting documents proving experience and competencies.', 'Full-time job', 'Applications must be submitted in soft copy as one single combined PDF document to the following email address: ask.recruitment26@gmail.com \r\nThe subject of the email must clearly indicate the position applied for: “Application for CLEANER.”\r\nDeadline for submission: 24th July, 2026 at 5:00 PM.\r\nLate applications will not be accepted.\r\nOnly shortlisted candidates will be contacted for the next stage of the recruitment process.', '', '', 'Eastern', 'Kayonza', 'Mukarange', 'Full-time', '1 year of experience', 'A2 DIPLOMA', 'RWF', 'monthly', '2026-07-24', 0, 'archived', 39, 0, 1, '2026-07-19 23:18:27', '2026-07-24 15:23:37', NULL),
(18, NULL, 'COOPEC IKIRENGA', 'logos/img_6a5f06081761f.jpeg', 9, 'TELLER', 'teller', 'COOPEC IKIRENGA is a Financial Service Cooperative operating in the Northern Province of Rwanda supervised by National Bank of Rwanda. Its creation is a result of merger of five SACCOs (COOPEC ITI, COOPEC CODEMARU, CSTCR SACCO, CSPKI and TRASO) that decided to form one single entity named “COOPEC IKIRENGA” in May, 2024 while the existing SACCOs remained as its branches. COOPEC IKIRENGA headquarter is located in Rulindo district, Base Sector, Rwamahwa Cell, Base Village.', 'Under the supervision and guidance of the Branch Operations Officer/Outlet responsible:\r\n\r\nConducts cash related services for customers/ members, e.g., withdrawals and deposits.\r\nInitiates transfers from customer/member accounts, e.g., interbranch transfer.\r\nPerforms cheques related services for customers/ members, e.g., crediting a cheque.\r\nSupports in day closure.\r\nSupports in opening, filling, discharging, and closing a till.\r\nPerforms cross-selling.', 'At least secondary education (A2) in Accounting, have a Bachelor Degree in Business Management, Finance, Accounting, Business Administration Economics or Related Field is a preferred Added Advantage.\r\nBasic IT literacy of CBS and Microsoft Office. \r\nAbility to handle transactions accurately and responsibly.\r\nGood math skills.\r\nAttention to detail.\r\nCustomer satisfaction oriented.', 'To be Rwandan\r\nAge limit: 30 Years\r\nNot to have been sentenced to a term of imprisonment equal to or exceeding six (6) months.\r\nNot to have been dismissed from any other institution unless applicant is entitled to reinstatement under laws and regulations in force.\r\nNot have been involved in the bankruptcy of a financial institution;', 'Full-time Job', 'Required documents for application:\r\nAn application letter addressed to the Chairperson of BoD of COOPEC IKIRENGA.\r\nA detailed/updated Curriculum Vitae.\r\nCopy of academic degree and Certificate where Required.\r\nA proof of work experience if any.\r\nA photocopy of the Identity card.\r\nFull addresses of three referees with recommendations letter, including preferably one of previous supervisors.\r\nNB: E-mail subject should be the Applicant Names followed by a Position is applying for.  recruitment@coopecikirenga.rw\r\nOnly shortlisted candidates will be contacted for the next stage of the recruitment process.\r\n\r\nDone at Base on the 16th July, 2026.\r\nMUSENGIMANA Joseph\r\nChairperson of Board of Directors of COOPEC IKIRENGA', '', 'recruitment@coopecikirenga.rw', 'Northern', 'RULINDO', '', 'Full-time', '', 'A2,A0', 'RWF', 'monthly', '2026-07-31', 1, 'published', 53, 0, 1, '2026-07-21 05:39:19', '2026-07-26 21:11:38', NULL),
(19, NULL, 'SUNPRINT LTD', 'logos/img_6a5f0c51c8f92.jpg', 14, 'Marketing Officer', 'marketing-officer', 'Sunprint Ltd is a corporate entity operating in Kigali, Rwanda. While the exact scope of their local operations is focused on sourcing and marketing, the company has recently been actively hiring for roles such as a Marketing Officer', 'Employee requirement\r\n\r\nFresh graduate with A0 degree in Procurement & supply chain or related options\r\nHas strong language skills especially English(four skills: Reading, Listening, Speaking& Writing)\r\nKnowledge of using personal computer and strongly apply M/S application (word, excel & power point).\r\nSmart in using social media and logical interpersonal skills\r\nBeing health, single and not beyond 26 years of age\r\nHas capacity to work under pressure and time management to meet deadlines\r\nBeing conducted trainings regarding Business ventures, marketing skills and procurement seminars (eProcurement system) is strongly encouraged to apply\r\nHaving the diving license category A & B is added advantage\r\nWilling to adapt and learn new skills\r\nAvailable and willing to conduct practical Exam and interview after being shortlisted', 'Application letter expressing interest for Marketing officer vacancy addressed to Managing Director of SUNPRINT LTD\r\nWell organized Curriculum Vitae(CV) only 2 pages\r\nAttach colored NID , Notified degrees and or other certificates and permits\r\nOther convincing attachment deemed necessary', '', 'Full-time Job', 'Send the one merged application document in pdf format to email of SUNPRINT Ltd; sunteckno@gmail.com\r\nDeadline for application on 15th August 2026 at 5pm', '', 'sunteckno@gmail.com', 'Kigali', '', '', 'Full-time', '1 to 3 years of experience', 'Bachelor&amp;#039;s Degree', 'RWF', 'monthly', '2026-08-15', 0, 'published', 38, 0, 1, '2026-07-21 06:06:09', '2026-07-26 21:19:08', NULL),
(20, NULL, 'U.H MINING COMPANY LTD', 'logos/img_6a5fd86e40ba0.jpeg', 2, 'MINING ENGINEERS', 'mining-engineers', 'About U.H Mining Company Ltd\r\n\r\nU.H Mining Company Ltd., a member of the RANI Group, is a growing mining company engaged in the exploration and extraction of strategic minerals in Rwanda. The company is committed to operational excellence, safety, innovation, sustainable mining practices, and responsible resource development.\r\n\r\nAs part of its expansion and mechanization program, U.H Mining Company Ltd. invites applications from suitably qualified, experienced, and motivated professionals to fill the position of Mining Engineer (7 positions).', 'Planning, coordinating and supervising underground and surface mining operations.\r\nPreparing mine development plans, production schedules and operational reports.\r\nMonitoring daily production targets and ensuring efficient mineral extraction.\r\nDesigning and implementing drilling and blasting programmes.\r\nEnsuring compliance with mining legislation, environmental regulations and occupational health and safety standards.\r\nCoordinating ventilation, ground support and mine infrastructure activities.\r\nConducting mine inspections and recommending operational improvements.\r\nWorking closely with Geologists, Surveyors, Processing Engineers and Maintenance teams.\r\nAssisting in the implementation of mechanised mining systems and continuous improvement initiatives.\r\nSupervising mining crews and contractors.\r\nPreparing technical reports and production forecasts.\r\nPerforming any other duties assigned by the Chief Operating Officer.', 'Applicants must possess:\r\nBachelor\'s degree in Mining Engineering from a recognised university.\r\nMinimum of three (3) years\' relevant mining experience (underground mining experience is an added advantage).\r\nKnowledge of mine planning and production software.\r\nGood understanding of drilling, blasting, ventilation and mine safety.\r\nStrong analytical, communication and leadership skills.\r\nAbility to work in remote mining locations.\r\nHigh level of integrity and professionalism.\r\nGood proficiency in both Kinyarwanda and English. Proficiency in French is an added advantage.', 'Leadership and supervision\r\nTechnical problem-solving\r\nProduction planning\r\nSafety management\r\nTeamwork\r\nExcellent communication skills\r\nAbility to work under pressure\r\nCommitment to continuous improvement', '', 'Application Procedure\r\n\r\nSubmit the following documents as one PDF attachment addressed to:\r\n\r\nThe Managing Director\r\nU.H Mining Company Ltd\r\n\r\nThe application must include:\r\n\r\nMotivation Letter\r\nCurriculum Vitae (CV) with three referees\r\nAcademic Certificates\r\nRelevant Work Certificates\r\nCopy of National ID or Passport\r\n\r\nApplication Deadline: Monday, 27 July 2026\r\n\r\nSubmit applications to: uh.mining@uh-mining.com\r\n\r\nFor inquiries, contact:\r\n\r\nBruce Kazungu\r\nHead of Administration and Legal Counsel\r\nTel: 0788309175\r\n\r\nOnly shortlisted candidates will be contacted.', '', 'uh.mining@uh-mining.com', '', '', '', 'Full-time', '3 YEARS OF EXPERIENCE', 'Bachelor&amp;#039;s Degree', 'RWF', 'monthly', '2026-07-27', 0, 'archived', 9, 0, 1, '2026-07-21 20:30:24', '2026-07-28 07:15:44', NULL),
(21, NULL, 'Nyungwe Management Company Ltd (NMC Ltd)', 'logos/img_6a5fdc53497b6.png', 9, 'Forest Restoration Team Leader (20 positions)', 'forest-restoration-team-leader-20-positions', 'NYUNGWE NATIONAL PARK VACANCY ANNOUNCEMENT\r\nNyungwe Management Company Ltd (NMC Ltd) was created by the management agreement between the Government of Rwanda (through RDB) and African Parks Network, to manage Nyungwe National Park for 20 years starting from October 2020. NMC Ltd is seeking to recruit suitable candidates to fill the post of Forest Restoration Team Leader in Nyungwe National Park. The candidates must be Rwandan, technically skilled with good problem-solving ability, be enthusiastic, motivated, reliable, and able to execute tasks independently.', 'ABOUT THE PROJECT\r\nNyungwe Management Company/African Parks (NMC/AP) is implementing a forest and landscape restoration initiative aimed at restoring degraded areas in Nyungwe National Park (NNP), as part of larger project “Building resilience of vulnerable communities to climate variability in Rwanda\'s Congo Nile Divide (CND) region through Forest and Landscape Restoration”, which is being implemented principally by the Rwanda Forestry Authority (RFA), and its implementing partners. Nyungwe Management Company will implement assisted natural forest rehabilitation of 4,500 ha of indigenous forest in NNP.\r\nSCOPE OF THE JOB\r\nThe Forest Restoration Team Leader is responsible for leading and supervising field teams engaged in assisted natural forest regeneration (ANFR), site maintenance, and monitoring. This role ensures that ANFR activities are implemented efficiently, safely, and in accordance with approved restoration plans and technical standards. The Team Leader acts as the key link between field workers and the Forest Restoration Field Coordinator.\r\nDuties and Key responsibilities (not exhaustive)\r\nField Activities Implementation, Leadership, Supervision, and Coordination\r\nLead daily ANFR activities such as fern cutting, site maintenance, and monitoring.\r\nSupervise casual laborers during field operations.\r\nEnsure ANFR activities follow technical guidelines, restoration plans, and environmental best practices,\r\nAllocate tasks to team members and ensure work targets are met on time,\r\nProvide on-site leadership, guidance, and motivation to the restoration team\r\nSupport team members through coaching and on-the-job training.\r\nPromote teamwork, discipline, environmental and social safety, and professional conduct in the field.\r\nMonitoring, Data Collection & Reporting\r\nCollect accurate field data, including GPS coordinates, seedling count, and growth, etc.\r\nSubmit regular field reports to the Forest Restoration Field Coordinator.\r\nReport challenges, risks, and field observations promptly.\r\nHealth, Safety & Compliance\r\nEnsure all field activities comply with health and safety standards.\r\nEnforce the proper use of tools and equipment, identify potential safety risks and take immediate corrective action.', 'Certificate (A2) or Diploma (A1) in Forestry, Environmental Management, Natural Resource Management, Agriculture, or a related field \r\nMedical Report\r\nCriminal Record\r\nMinimum of 6 months of hands-on experience in forest restoration or natural resource management.\r\nProven experience supervising or leading field teams is an added advantage.\r\nHaving worked in ANFR in Nyungwe National Park is an added advantage\r\nProblem-solving and decision-making ability\r\nPractical knowledge of Assisted natural forest restoration techniques', 'Working Conditions\r\nPrimarily field-based in remote restoration sites\r\nRequires physical work under varying weather conditions\r\nMay involve staying many days (±20 days) working in a remote area at a forest restoration site\r\nNote \r\n\r\nApplications that do not meet the above criteria will not be considered.', 'Full-time Job', 'Interested candidates should forward their application letter together with all relevant documents to the email address provided below no later than 28th July 2026. The required documents should be submitted in scanned soft copies in pdf format (preferably as one document) on nmc.recruit@africanparks.org. The successful candidate will begin with an immediate effect.\r\n\r\nApplications must include the following documents:\r\nApplication cover letter addressed to the Park Manager\r\nStating where you heard about the position and why you should be considered\r\nCurriculum vitae including your personal details, education level, and any experience \r\nCriminal record and medical report (failure to submit a valid Criminal Record Certificate and medical report will result in disqualification) \r\nName, address, and telephone numbers of three (3) references\r\nAll the documents should be in one pdf document and named after your name and position, for example: Name, Nyungwe Forest Restoration Team Leader, 2026.\r\nPlease note that only candidates with the qualifications needed and relevant experience will be shortlisted. If you don\'t hear from us within one week after the submission deadline, know that you have not been shortlisted.\r\n\r\nDone in Nyungwe National Park on 15th July 2026.\r\nNIYIGABA Protais\r\nPark Manager/CEO\r\nNyungwe Management Company', '', 'nmc.recruit@africanparks.org', 'Western', 'nyamasheke', '', 'Full-time', 'Entry level (1 to 3 years of experience)', 'Diploma', 'RWF', 'monthly', '2026-07-28', 1, 'archived', 333, 0, 1, '2026-07-21 20:53:39', '2026-07-29 07:24:41', NULL);
