(1, 'University Financial Aid', 'Rwandan universities such as the University of Rwanda, Carnegie Mellon University Africa, and Africa Leadership University offer internal financial aid and merit-based scholarships.', 'fas fa-university', 'bg-blue-50', 'text-blue-500', 'View Scholarships', 'university', 1, 1, '2026-07-17 15:16:45', '2026-07-17 15:27:51'),
(2, 'NGO & Private Scholarships', 'Organizations like the Mastercard Foundation Scholars Program, We Are All The Same, and various NGOs provide scholarship funding for talented Rwandan youth.', 'fas fa-hand-holding-heart', 'bg-green-100', 'text-green-600', 'View Scholarships', 'ngo', 1, 2, '2026-07-17 15:16:45', '2026-07-17 15:27:51');

