INSERT INTO `scholarship_listings` (`id`, `scholarship_id`, `title`, `organization`, `banner_image`, `description`, `eligibility`, `deadline`, `link_url`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'Mastercard Foundation Masters Scholarship – University of Rwanda 2026–2027', 'Mastercard Foundation / University of Rwanda', 'banners/img_6a671c3e531ef.jpeg', 'The Mastercard Foundation Scholars Program, in partnership with the University of Rwanda, is now accepting applications for the 3rd Cohort of Master&#039;s Scholarships for the 2026–2027 Academic Year.\r\n\r\nWhat the scholarship offers:\r\n- Full tuition fees\r\n- Accommodation\r\n- Laptop and learning materials\r\n- Academic mentorship\r\n- Leadership development\r\n- Psychosocial support\r\n- Internship and career development opportunities\r\n- Other support for eligible scholars\r\n\r\nWho should apply? Academatically talented students from Rwanda and other African countries who face social or economic barriers, demonstrate leadership potential, and are committed to giving back to their communities. The program is intended for newly admitted University of Rwanda students who have not yet started their studies.', 'Academically talented students from Rwanda and other African countries who face social or economic barriers, demonstrate leadership potential, and are committed to giving back to their communities. Must be newly admitted University of Rwanda students who have not yet started their studies.\r\n\r\nEligible Master&#039;s programs include:\r\n- MSc in Information Technology\r\n- MSc in Data Science\r\n- MSc in Computer Science\r\n- MSc in Information Systems\r\n- MSc in Artificial Intelligence\r\n- MSc in Engineering (selected specializations)\r\n- MSc in Agriculture (selected programs)\r\n- MSc in Health Sciences (selected programs)\r\n- MSc in Business and Economics (selected programs)\r\n- Other eligible University of Rwanda Master&#039;s programmes listed on the official portal.', '2026-08-22', 'https://mcfsprecruitment.ur.ac.rw/', 1, 0, '2026-07-27 08:52:13', '2026-07-27 08:52:13');

